import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import java.util.*;

public final class StarterDeck100PassiveRuleTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    public static void main(String[] args){for(String mode:List.of("ACTIVE","BENCH","DISABLED","IMMUNE"))burn(mode);burst();corviknight();for(boolean switched:List.of(false,true))hurricane(switched);for(String mode:List.of("SELF","BENCH","EMPTY","DISABLED"))solar(mode);existingStatus();mindstorm();System.out.println("StarterDeck100PassiveRuleTest passed: live Burn recovery, real coins, immunity FAQ, attack-effect versus damage distinction, energized field recipients, pre-existing status, suppression and next-turn attack lock");}
    static void burn(String mode){boolean sawHeads=false,sawTails=false;for(int seed=0;seed<100&&(!sawHeads||!sawTails);seed++){
        var m=StarterDeck100PokemonTest.gameSeed(75,mode.equals("IMMUNE")?310:1,seed);var source=m.activePokemonView(A).pokemonId();if(mode.equals("IMMUNE")){m.endTurn(A);StarterDeck100GuardTest.prepareOpponent(m,310,0);m.endTurn(B);}if(mode.equals("BENCH"))m.switchActiveByEffect(A,A,m.benchPokemonView(A).getFirst().pokemonId());if(mode.equals("DISABLED"))m.disableAbilityEffectsByEffect(A,A,source);
        m.applySpecialConditionByEffect(A,B,SpecialCondition.BURNED);int rng=m.randomTranscript().size();m.endTurn(A);var coin=m.randomTranscript().subList(rng,m.randomTranscript().size()).stream().filter(e->e.operation().equals("checkup-burn:"+B)).toList();check(coin.size()==1,"Overheater skipped or repeated Burn coin");boolean heads=coin.getFirst().result()==0;sawHeads|=heads;sawTails|=!heads;boolean blocked=mode.equals("ACTIVE")||mode.equals("BENCH");check(m.activePokemonView(B).damage()==20&&m.activePokemonView(B).conditions().contains(SpecialCondition.BURNED)==(blocked||!heads),"Burn recovery/source/immunity mismatch: "+mode);
    }check(sawHeads&&sawTails,"Burn coin coverage incomplete: "+mode);}
    static void burst(){var m=StarterDeck100PokemonTest.game(75,310);m.endTurn(A);StarterDeck100GuardTest.prepareOpponent(m,310,0);m.endTurn(B);StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==260&&m.activePokemonView(B).damage()==280,"Burst Inferno130 before Fire weakness, then20 Burn damage");}
    static void corviknight(){for(boolean disabled:List.of(false,true)){var m=StarterDeck100PokemonTest.game(310,118);var target=m.activePokemonView(A).pokemonId();if(disabled)m.disableAbilityEffectsByEffect(A,A,target);m.endTurn(A);StarterDeck100GuardTest.prepareOpponent(m,118,0);m.useAbility(B,m.activePokemonView(B).pokemonId(),"quick-shooting",target);check(m.activePokemonView(A).damage()==(disabled?20:0),"Lustrous Body did not prevent opponent Ability counters or remained after suppression");m.placeDamageCountersByEffect(B,A,target,1);check(m.activePokemonView(A).damage()==(disabled?30:10),"Ability immunity blocked rule-origin counters");}}
    static void hurricane(boolean switched){var m=StarterDeck100PokemonTest.game(310,310);m.endTurn(A);StarterDeck100GuardTest.prepareOpponent(m,310,0);m.endTurn(B);StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==240,"Hurricane damage");m.endTurn(B);TopDeckLookTest.rejects(()->m.attack(A,"g-max-hurricane"));if(switched){var source=m.activePokemonView(A).pokemonId();m.switchActiveByEffect(A,A,m.benchPokemonView(A).getFirst().pokemonId());m.switchActiveByEffect(A,A,source);}else{m.endTurn(A);m.endTurn(B);}m.attack(A,"g-max-hurricane");check(m.lastAttack().finalDamage()==240,"Hurricane lock failed to clear at next turn end/switch");}
    static void solar(String mode){var m=StarterDeck100PokemonTest.game(173,259);var source=m.activePokemonView(A).pokemonId();if(mode.equals("BENCH"))m.switchActiveByEffect(A,A,m.benchPokemonView(A).getFirst().pokemonId());var target=m.activePokemonView(A).pokemonId();if(!mode.equals("EMPTY"))StarterDeck100EnergyTest.attach(m,A,A,"sd100_cn_grass_energy",target);if(mode.equals("DISABLED"))m.disableAbilityEffectsByEffect(A,A,source);m.endTurn(A);StarterDeck100GuardTest.attackOpponent(m,259,0);boolean guarded=!mode.equals("EMPTY")&&!mode.equals("DISABLED");check(m.lastAttack().finalDamage()==20&&m.activePokemonView(A).damage()==(guarded?20:140),"Solar Revelation prevented damage or failed to block poison: "+mode);check(m.activePokemonView(A).conditions().contains(SpecialCondition.POISONED)==!guarded,"Solar Revelation status mismatch");}
    static void existingStatus(){var m=StarterDeck100PokemonTest.game(173);var target=m.activePokemonView(A).pokemonId();m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);StarterDeck100EnergyTest.attach(m,A,A,"sd100_cn_grass_energy",target);check(m.activePokemonView(A).conditions().contains(SpecialCondition.POISONED),"Solar Revelation removed existing poison");m.endTurn(A);check(m.activePokemonView(A).damage()==10,"existing poison stopped damaging after protection");}
    static void mindstorm(){var m=StarterDeck100PokemonTest.game(173,1,"sm1_en_136");var special=m.privateView(A).deck().stream().filter(c->c.definitionId().equals("sm1_en_136")).findFirst().orElseThrow();m.attachEnergyByEffect(A,A,EffectSourceZone.DECK,special.instanceId(),B,m.activePokemonView(B).pokemonId());for(int i=0;i<2;i++)StarterDeck100EnergyTest.attach(m,A,B,"sd100_cn_grass_energy",m.benchPokemonView(B).getFirst().pokemonId());StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==240,"Max Mindstorm counted cards instead of units or skipped opposing Bench");}
}
